function lrEsc(v){return String(v==null?'':v).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));}
function lrToolboxHTML(level){const a=LR_THEORY[level];return a?'<details class="lr-toolbox"><summary>📚 Caja de herramientas · '+level+'</summary><div class="lr-toolbox-body"><p>Consulta estas reglas cuando las necesites.</p>'+a.map(x=>'<section class="lr-tool-row"><b>'+lrEsc(x[0])+'</b><p>'+lrEsc(x[1])+'</p></section>').join('')+'</div></details>':'';}
function lrExplain(){if(!run)return;const q=worlds[run.w].missions[run.m].qs[run.q],level=worlds[run.w].level,answer=(q[5]==='order'||q[5]==='speak')?q[6]:(q[1]&&q[1][q[2]])||q[3]||'',src=[q[0],q[3],q[4],answer].join(' ').toLowerCase(),rules=[];const add=(a,b,c)=>rules.push({a,b,c});
if(/\bweil\b/.test(src))add('weil + verbo al final','Weil introduce una subordinada. El verbo conjugado va al final.','Ich lerne Deutsch, weil ich in der Schweiz lebe.');
if(/\bdeshalb\b|\bfolglich\b|\binfolgedessen\b/.test(src))add('Conector de consecuencia','Si deshalb ocupa la primera posición, el verbo conjugado va inmediatamente después.','Es regnet. Deshalb bleiben wir zu Hause.');
if(/\bobwohl\b/.test(src))add('obwohl + verbo al final','Obwohl expresa contraste y lleva el verbo conjugado al final.','Obwohl es regnet, gehen wir spazieren.');
if(/\btrotzdem\b/.test(src))add('trotzdem + verbo en segunda posición','Trotzdem conecta con una oración principal; si va al inicio, después va el verbo.','Es regnet. Trotzdem gehen wir spazieren.');
if(/interessier/.test(src)&&/für/.test(src))add('sich interessieren für + Akkusativ','Aprende la estructura completa. El pronombre reflexivo depende del sujeto y el complemento con für va en Akkusativ.','Ich interessiere mich für Informatik.');
if(/\bwarten\b|\bwarte\b/.test(src)&&/auf/.test(src))add('warten auf + Akkusativ','warten exige auf en esta estructura; el complemento va en Akkusativ.','Ich warte auf den Bus. (der Bus → den Bus)');
if(/\bhelfen\b/.test(src))add('helfen + Dativ','helfen rige Dativ: mir, dir, meiner Freundin.','Ich helfe meiner Freundin.');
if(/\bwenn\b/.test(src))add('wenn + verbo al final','Wenn introduce una condición; el verbo conjugado va al final de la subordinada.','Wenn ich Zeit habe, rufe ich dich an.');
if(/perfekt|gearbeitet|gefahren|gegangen|besucht/.test(src))add('Perfekt: auxiliar + participio','El participio suele ir al final. Muchos verbos usan haben; verbos de movimiento/cambio suelen usar sein.','Ich habe gearbeitet. / Ich bin nach Hause gegangen.');
if(/akkusativ|artikel|\bder\b|\bdie\b|\bdas\b|\beinen\b/.test(src))add('Artículos y casos','En Akkusativ masculino: der → den, ein → einen. En Dativ femenino: die → der. El verbo o la preposición determina el caso.','Ich sehe den Mann. / Ich helfe der Frau.');
if(/konjunktiv i|\bsei\b/.test(src))add('Konjunktiv I','Se usa especialmente para reproducir lo que otra persona dice en estilo indirecto.','Sie sagt, sie sei krank.');
if(/position 2|zweite position|verbo.*final|orden correcto|ordena la frase/.test(src)||q[5]==='order')add('Posición del verbo','En una principal el verbo conjugado suele estar en segunda posición. En subordinadas con weil/obwohl/wenn, va al final.','Heute arbeite ich. / …, weil ich heute arbeite.');
if(!rules.length)add('Cómo aprender esta respuesta','Observa la expresión completa, su significado y el ejemplo. Intenta crear otra frase con la misma estructura.',String(answer));
const box=$('lr-explanation-detail');if(!box)return;box.innerHTML='<div class="lr-explanation-head"><b>📖 Explicación detallada · '+level+'</b><button onclick="Lernreise.hideExplanation()">Cerrar ✕</button></div><p><b>Respuesta modelo:</b> '+lrEsc(answer)+'</p><p><b>Explicación de la misión:</b> '+lrEsc(q[3]||'Compara tu respuesta con el modelo.')+'</p><p><b>Pista:</b> '+lrEsc(q[4]||'Identifica el verbo conjugado, el conector y la preposición.')+'</p>'+rules.map(r=>'<section class="lr-explain-rule"><b>'+lrEsc(r.a)+'</b><p>'+lrEsc(r.b)+'</p><p class="lr-explain-example">Beispiel: '+lrEsc(r.c)+'</p></section>').join('')+'<p class="lr-explain-level">Nivel '+level+' · Revisa la estructura y aplícala en otra frase.</p>';box.hidden=false;}
function lrHideExplanation(){const b=$('lr-explanation-detail');if(b)b.hidden=true;}
